struct SegmentHeader {
    uint16_t size;
    uint32_t magic;
    char payload[1];
};

// Pointer arithmetic across aligned/unaligned structures
struct SegmentHeader* current_seg;
ptrdiff_t stride = sizeof(uint16_t) + sizeof(uint32_t);

// Advance pointer to the start of the next header
current_seg = (struct SegmentHeader*)
    ((char*)current_seg + stride + current_seg->size);


// --- Segment boundary access/MMIO Simulation ---

#define VEC_TABLE_BASE 0x0000FF00

// Access specific memory address location (e.g., Interrupt Vector)
volatile uint32_t* vector_table =
    (volatile uint32_t*)VEC_TABLE_BASE;

// Read entry 5
uint32_t vector_entry = vector_table[5];

// Type punning to inspect raw bytes across a boundary
uint8_t raw_byte = *(uint8_t*)
    ((char*)&vector_table[1] - 1);
